#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."

echo "==> Ensuring docker compose services are up"
docker compose up -d >/dev/null

if [[ -n "${CODESPACE_NAME:-}" && -n "${GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN:-}" ]]; then
  MERCURE_PUBLIC_URL="https://${CODESPACE_NAME}-9090.${GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN}/.well-known/mercure"

  cat > .env.local <<EOF
# Auto-generated by .devcontainer/post-start.sh — do not edit by hand.
# Overrides NEXT_PUBLIC_MERCURE_URL so the browser reaches Mercure via the
# Codespaces forwarded port instead of localhost:9090.
NEXT_PUBLIC_MERCURE_URL=${MERCURE_PUBLIC_URL}
EOF

  echo "==> Wrote .env.local with NEXT_PUBLIC_MERCURE_URL=${MERCURE_PUBLIC_URL}"
else
  echo "==> Not running inside Codespaces (CODESPACE_NAME unset); skipping .env.local override."
fi
